objectives.dqlQuery:
timeseries {
  cpu_throttled_time=avg(dt.containers.cpu.throttled_time)
},
  by: {k8s.namespace.name},
  filter: {k8s.namespace.name == "astroshop"}
| fields `average throttling/min`=arrayAvg(cpu_throttled_time)/1000000

timeseries {
  totalMem = sum(dt.kubernetes.container.memory_working_set)
}, filter: { k8s.namespace.name == "astroshop" }
| fields totalMemoryInMb = arrayMax(totalMem) / 1000 / 1000

timeseries {
  totalCpu = sum(dt.kubernetes.container.cpu_usage)
}, filter: { k8s.namespace.name == "astroshop" }
| fields totalCpuInMillicores = arrayMax(totalCpu)
